// DnsZoneServiceHandler is an implementation of the rpmgr.v1.DnsZoneService service.
type DnsZoneServiceHandler interface {
	// ImportZone imports a zone of a connected provider as a managed zone, held. Only a zone that
	// the provider calls active and full can be imported. The import creates the claim on the
	// zone's apex, wildcard included, unless the org has a verified domain that covers it; a zone
	// that is pending at the provider, or that another org claimed, is not imported, and a zone at
	// the provider is no proof of ownership: the claim is verified like any other.
	ImportZone(context.Context, *connect.Request[v1.ImportZoneRequest]) (*connect.Response[v1.ImportZoneResponse], error)
	// GetZone returns a managed zone.
	GetZone(context.Context, *connect.Request[v1.GetZoneRequest]) (*connect.Response[v1.GetZoneResponse], error)
	// ListZones lists an org's managed zones by ID.
	ListZones(context.Context, *connect.Request[v1.ListZonesRequest]) (*connect.Response[v1.ListZonesResponse], error)
	// UpdateZone changes the gates and the default TTL of a zone.
	UpdateZone(context.Context, *connect.Request[v1.UpdateZoneRequest]) (*connect.Response[v1.UpdateZoneResponse], error)
	// RemoveZone stops managing a zone. The records stay at the provider and so does the apex claim,
	// unless delete_records asks for the records to be deleted.
	RemoveZone(context.Context, *connect.Request[v1.RemoveZoneRequest]) (*connect.Response[v1.RemoveZoneResponse], error)
	// PlanZoneSync computes the plan of a zone now: what a pass would create, change and delete, the
	// conflicts it found, the records that carry this instance's marker without a ledger row, and the
	// hash an approval is bound to. The provider's records are read live and nothing is written.
	PlanZoneSync(context.Context, *connect.Request[v1.PlanZoneSyncRequest]) (*connect.Response[v1.PlanZoneSyncResponse], error)
	// SyncZone asks for a full pass over the zone now: the DNS job, on the replica that holds its
	// lease, lists the provider and reconciles at its next tick, without the debounce. The answer
	// does not wait for it.
	SyncZone(context.Context, *connect.Request[v1.SyncZoneRequest]) (*connect.Response[v1.SyncZoneResponse], error)
	// ListZoneRecords lists the records rpmgr owns in a zone, from the ownership ledger, and with
	// include_foreign the other records of the zone, read live from the provider. Any member of the
	// org may list the owned records; the foreign ones, which show what else is in the zone, only
	// an Owner or Admin may ask for.
	ListZoneRecords(context.Context, *connect.Request[v1.ListZoneRecordsRequest]) (*connect.Response[v1.ListZoneRecordsResponse], error)
	// AdoptRecords turns foreign records at names the zone publishes into owned ones: each gets a
	// ledger row that keeps its original content, and the next pass rewrites it. All or none: a
	// record that does not exist, is owned already, has a type rpmgr does not manage, or lies at a
	// name no source of the org publishes fails the call.
	AdoptRecords(context.Context, *connect.Request[v1.AdoptRecordsRequest]) (*connect.Response[v1.AdoptRecordsResponse], error)
	// ReleaseRecord asks for an owned record to leave the ledger, so that rpmgr never changes it
	// again. The DNS job carries it out under its lease, at its next pass of an active zone: the
	// record stays at the provider, without rpmgr's marker, or with restore it is put back to the
	// content it had when it was adopted. Until then the record shows the request in its reason.
	// AdoptRecords and ReleaseRecord need a step-up: they hand rpmgr control of a record, or take
	// it back.
	ReleaseRecord(context.Context, *connect.Request[v1.ReleaseRecordRequest]) (*connect.Response[v1.ReleaseRecordResponse], error)
	// EnableZone moves a disabled zone, such as one that restore --dns-disabled disabled, to held.
	// It writes nothing: the zone computes plans again and needs an approved plan before the job
	// writes to the provider. It needs a step-up. A zone that is not disabled is
	// FAILED_PRECONDITION with ZONE_NOT_DISABLED.
	EnableZone(context.Context, *connect.Request[v1.EnableZoneRequest]) (*connect.Response[v1.EnableZoneResponse], error)
	// ApproveZonePlan approves the plan with the hash: the zone becomes active and the next pass
	// applies that plan and no other. It fails with PLAN_CHANGED, and nothing changes, if the plan
	// now has another hash. A zone that is not held, such as one that a restore disabled, is
	// FAILED_PRECONDITION with ZONE_NOT_HELD. It needs a step-up.
	ApproveZonePlan(context.Context, *connect.Request[v1.ApproveZonePlanRequest]) (*connect.Response[v1.ApproveZonePlanResponse], error)
}

